import jax, jax.numpy as jnp
from jax.experimental import pallas as pl
# kb__l1__01_Relu_Scale.a1.s0
def _k(x_ref, o_ref):
    o_ref[...] = jnp.maximum(x_ref[...], 0.0) * 2.0
def workload(x):
    return pl.pallas_call(_k, out_shape=jax.ShapeDtypeStruct(x.shape, x.dtype), grid=(x.shape[0] // 8,),
        in_specs=[pl.BlockSpec((8, 128), lambda i: (i, 0))], out_specs=pl.BlockSpec((8, 128), lambda i: (i, 0)))(x)

